def remove_item(inventory, name):
    count = inventory.get(name, 0)
    if count <= 1:
        inventory.pop(name, None)
    else:
        inventory[name] = count - 1
    return inventory

from src.inventory import remove_item


def test_remove_present_item_decrements():
    inventory = {"pen": 2}
    assert remove_item(inventory, "pen") == {"pen": 1}


def test_remove_last_item_deletes_key():
    inventory = {"pen": 1}
    assert remove_item(inventory, "pen") == {}


def test_remove_absent_item_raises_key_error():
    try:
        remove_item({}, "pen")
    except KeyError:
        return
    raise AssertionError("expected KeyError")


if __name__ == "__main__":
    test_remove_present_item_decrements()
    test_remove_last_item_deletes_key()
    test_remove_absent_item_raises_key_error()

