export function median(values: number[]): number {
  if (values.length === 0) throw new Error("empty input");
  values.sort((a, b) => a - b);
  const middle = Math.floor(values.length / 2);
  if (values.length % 2 === 1) return values[middle];
  return (values[middle - 1] + values[middle]) / 2;
}

import { median } from "../src/stats";

const values = [3, 1, 2];
if (median(values) !== 2) throw new Error("wrong median");
if (values.join(",") !== "3,1,2") throw new Error("median mutated input");

const even = [4, 1, 3, 2];
if (median(even) !== 2.5) throw new Error("wrong even median");
if (even.join(",") !== "4,1,3,2") throw new Error("median mutated even input");

