package limiter

type Limiter struct {
	Limit int
	Used  int
}

func (l *Limiter) Allow() bool {
	if l.Used < l.Limit {
		l.Used++
		return true
	}
	return l.Limit == 0
}

package limiter

import "testing"

func TestAllowPositiveLimit(t *testing.T) {
	l := &Limiter{Limit: 2}
	if !l.Allow() || !l.Allow() || l.Allow() {
		t.Fatalf("unexpected allowance sequence")
	}
}

func TestAllowZeroOrNegativeLimit(t *testing.T) {
	if (&Limiter{Limit: 0}).Allow() {
		t.Fatalf("zero limit should not allow")
	}
	if (&Limiter{Limit: -1}).Allow() {
		t.Fatalf("negative limit should not allow")
	}
}

