use std::collections::HashMap;

pub fn parse_ini(input: &str) -> HashMap<String, String> {
    let mut values = HashMap::new();
    for line in input.lines() {
        let trimmed = line.trim();
        if trimmed.is_empty() || trimmed.starts_with('#') {
            continue;
        }
        if let Some((key, value)) = trimmed.split_once('=') {
            values.insert(key.trim().to_string(), value.trim().to_string());
        }
    }
    values
}

#[cfg(test)]
mod tests {
    use super::parse_ini;

    #[test]
    fn parses_values_and_ignores_comments() {
        let parsed = parse_ini("# old\n; new\n host = local ");
        assert_eq!(parsed.get("host"), Some(&"local".to_string()));
        assert!(!parsed.contains_key("; new"));
    }
}

