public final class EmailValidator {
    private EmailValidator() {}

    public static boolean isValid(String value) {
        if (value == null) {
            return false;
        }
        return value.contains("@") && value.indexOf('@') > 0 && value.indexOf('@') < value.length() - 1;
    }
}

public final class EmailValidatorTest {
    public static void main(String[] args) {
        assertValid("name@example.com");
        assertValid("  name@example.com  ");
        assertInvalid("missing-at");
        assertInvalid("@example.com");
    }

    private static void assertValid(String value) {
        if (!EmailValidator.isValid(value)) throw new AssertionError(value + " should be valid");
    }

    private static void assertInvalid(String value) {
        if (EmailValidator.isValid(value)) throw new AssertionError(value + " should be invalid");
    }
}

