using System;
using System.Linq;

public static class PasswordPolicy
{
    public static bool IsStrong(string password)
    {
        if (string.IsNullOrEmpty(password) || password.Length < 8) return false;
        return password.Any(char.IsUpper)
            && password.Any(char.IsLower)
            && password.Any(char.IsDigit);
    }
}

using System;

public static class PasswordPolicyTest
{
    public static void Main()
    {
        AssertStrong("GoodPass1!");
        AssertWeak("GoodPass1");
    }

    static void AssertStrong(string value)
    {
        if (!PasswordPolicy.IsStrong(value)) throw new Exception(value + " should be strong");
    }

    static void AssertWeak(string value)
    {
        if (PasswordPolicy.IsStrong(value)) throw new Exception(value + " should be weak");
    }
}

