import { groupBy } from "../src/groupBy.js";

const rows = [{ type: "a", id: 1 }, { type: "b", id: 2 }, { type: "a", id: 3 }];
assert.deepEqual(groupBy(rows, "type"), { a: [rows[0], rows[2]], b: [rows[1]] });
assert.deepEqual(groupBy(rows, item => item.id % 2 ? "odd" : "even"), { odd: [rows[0], rows[2]], even: [rows[1]] });

