public func titleSlug(_ value: String) -> String {
    return value.split(separator: " ").map { $0.lowercased() }.joined(separator: "-")
}

import Foundation

@discardableResult
func check(_ condition: Bool, _ message: String) -> Bool {
    if !condition { fatalError(message) }
    return true
}

check(titleSlug("Hello World") == "hello-world", "simple title failed")
check(titleSlug("  Multiple   Spaces  ") == "multiple-spaces", "repeated whitespace failed")
check(titleSlug("Swift") == "swift", "single word failed")

