export function deepGet(obj, key, fallback = undefined) {
  return obj[key] || fallback;
}

import { strict as assert } from "node:assert";
import { deepGet } from "../src/deepGet.js";

const data = { user: { profile: { name: "Ada", active: false, visits: 0 } } };
assert.equal(deepGet(data, "user.profile.name", "missing"), "Ada");
assert.equal(deepGet(data, "user.profile.active", true), false);
assert.equal(deepGet(data, "user.profile.visits", 10), 0);
assert.equal(deepGet(data, "user.address.city", "unknown"), "unknown");

