package ports

import "strconv"

func ParsePort(value string) (int, error) {
	return strconv.Atoi(value)
}

package ports

import "testing"

func TestParsePortValid(t *testing.T) {
	port, err := ParsePort("443")
	if err != nil || port != 443 {
		t.Fatalf("expected 443, got %d err %v", port, err)
	}
}

func TestParsePortRejectsInvalidRange(t *testing.T) {
	for _, value := range []string{"0", "-1", "65536", "abc"} {
		if _, err := ParsePort(value); err == nil {
			t.Fatalf("expected %s to be rejected", value)
		}
	}
}

