import java.util.LinkedHashMap;
import java.util.Map;

public final class PropertiesParser {
    private PropertiesParser() {}

    public static Map<String, String> parse(String text) {
        Map<String, String> values = new LinkedHashMap<>();
        for (String line : text.split("\\n")) {
            String[] parts = line.split("=", 2);
            values.put(parts[0], parts[1]);
        }
        return values;
    }
}

import java.util.Map;

public final class PropertiesParserTest {
    public static void main(String[] args) {
        Map<String, String> parsed = PropertiesParser.parse(" host = local \n  # comment\n\nport=8000\n");
        if (!"local".equals(parsed.get("host"))) throw new AssertionError("host failed");
        if (!"8000".equals(parsed.get("port"))) throw new AssertionError("port failed");
        if (parsed.containsKey("# comment")) throw new AssertionError("comment was not skipped");
    }
}

