def read_table(text):
    return list(csv.DictReader(StringIO(text)))

from src.table import read_table


def test_read_table_crlf_trim_header_skip_blank():
    rows = read_table(' name ,age\r\nAda,36\r\n\r\nGrace,85\r\n')
    assert rows == [{'name': 'Ada', 'age': '36'}, {'name': 'Grace', 'age': '85'}]


if __name__ == '__main__':
    test_read_table_crlf_trim_header_skip_blank()

export function parseEnv(text) {
  const result = {};
  for (const line of text.split('\n')) {
    const [key, value] = line.split('=');
    result[key] = value;
  }
  return result;
}

import { strict as assert } from 'node:assert';
import { parseEnv } from '../src/env.js';

assert.deepEqual(parseEnv('HOST=local\r\n# comment\r\n\r\nPORT=8000\r\n'), { HOST: 'local', PORT: '8000' });

